def group_by_key(dict_list, key):
    """Groups a list of dictionaries by the value of a given key."""
    grouped = {}
    for item in dict_list:
        value = item[key]
        if value not in grouped:
            grouped[value] = []
        grouped[value].append(item)
    return grouped
